        /// <summary>Total tiles in the export, so callers can size buffers up front.</summary>
        public const int TileCount = 600;

        /// <summary>Rounds a world position to the id of the tile that contains it.</summary>
        public static int TileAt(Vector3 world)
        {
            int column = Mathf.Clamp(Mathf.FloorToInt(world.x / 64f), 0, 24);
            int row = Mathf.Clamp(Mathf.FloorToInt(world.z / 64f), 0, 24);
            return (row * 25) + column;
        }
    }
